    public static boolean has(String name) { return ICONS.containsKey(name); }

    /** Draws the 9x9 icon with its top-left at x, y; {@code px} is the pixel size. */
    public static void draw(GuiGraphics g, String name, int x, int y, int px, int color) {
        String[] rows = ICONS.get(name);
        if (rows == null) rows = ICONS.get("_grid");
        for (int r = 0; r < rows.length; r++) {
            String row = rows[r];
            int c = 0;
            while (c < row.length()) {   // one fill per run of pixels
                if (row.charAt(c) != '#') { c++; continue; }
                int s = c;
                while (c < row.length() && row.charAt(c) == '#') c++;
                g.fill(x + s * px, y + r * px, x + c * px, y + r * px + px, color);
            }
        }
    }
